from contextlib import contextmanager


class Command(object):

    def __init__(self, remote_shell):
        self._remote_shell = remote_shell


class ConfigModeCommand(Command):
    mode_cmd = 'config'
    exit_cmd = 'exit'
    expected_mode_prompt = None

    @contextmanager
    def __call__(self):
        self._remote_shell.sendline(self.mode_cmd)
        self._check_output()
        try:
            yield
        finally:
            self._remote_shell.sendline(self.exit_cmd)

    def _check_output(self):
        if self.expected_mode_prompt is None:
            return
        self._remote_shell.expect_exact(self.expected_mode_prompt)


class QuantaConfigModeCommand(ConfigModeCommand):
    expected_mode_prompt = '(Config)#'


class DellConfigModeCommand(ConfigModeCommand):
    expected_mode_prompt = '(conf)#'


class SystemVersionCommand(Command):
    command = 'show version'

    def __call__(self):
        self._remote_shell.sendline(self.command)
        return self._remote_shell.expect_exact('#')
